// b: 4 lanes x 8 bits, lane i = b[i*8 +: 8]
module mac4 (
    input  logic clk,
    input  logic rst_n,
    input  logic start,
    input  logic [31:0] a,
    input  logic [31:0] b,
    output logic [21:0] acc,
    output logic done
);

    localparam logic [1:0] IDLE = 2'd0, RUN = 2'd1, DONE = 2'd2;
    logic [1:0] state, nxt_state;
    logic [3:0] ctr, nxt_ctr;
    logic [21:0] acc_reg, nxt_acc;
    logic done_reg, nxt_done;
    logic [15:0] prod [3:0];
    logic [17:0] sum_prods;

    always_comb begin
        sum_prods = 18'd0;
        for (int i = 0; i < 4; i++) begin
            prod[i] = a[i*8 +: 8] * b[i*8 +: 8];
            sum_prods = sum_prods + prod[i];
        end
    end

    always_comb begin
        nxt_state = state;
        nxt_ctr = ctr;
        nxt_acc = acc_reg;
        nxt_done = done_reg;

        case (state)
            IDLE: begin
                nxt_done = 1'b0;
                if (start) begin
                    nxt_state = RUN;
                    nxt_ctr = 4'd0;
                    nxt_acc = 22'd0;
                end
            end
            RUN: begin
                nxt_acc = acc_reg + sum_prods;
                nxt_ctr = ctr + 1'b1;
                if (ctr == 4'd15) begin
                    nxt_state = DONE;
                    nxt_done = 1'b1;
                end
            end
            DONE: begin
                nxt_done = 1'b1;
            end
        endcase
    end

    always_ff @(posedge clk) begin
        if (!rst_n) begin
            state <= IDLE;
            ctr <= 4'd0;
            acc_reg <= 22'd0;
            done_reg <= 1'b0;
        end else begin
            state <= nxt_state;
            ctr <= nxt_ctr;
            acc_reg <= nxt_acc;
            done_reg <= nxt_done;
        end
    end

    assign acc = acc_reg;
    assign done = done_reg;

endmodule

