        // drive next-state signals
        run = nxt_run;
        cnt = nxt_cnt;
        acc_reg = nxt_acc;
        done_reg = nxt_done;
    end

    always_ff @(posedge clk) begin
        if (!rst_n) begin
            run     <= 1'b0;
            cnt     <= 4'd0;
            acc_reg <= 22'd0;
            done_reg<= 1'b0;
        end else begin
            run     <= nxt_run;
            cnt     <= nxt_cnt;
            acc_reg <= nxt_acc;
            done_reg<= nxt_done;
        end
    end

    assign acc = acc_reg;
    assign done = done_reg;

endmodule

// a: 4 lanes x 8 bits, lane i = a[i*8 +: 8]
// b: 4 lanes x 8 bits, lane i = b[i*8 +: 8]
module mac4 (
    input  logic clk,
    input  logic rst_n,
    input  logic start,
    input  logic [31:0] a,
    input  logic [31:0] b,
    output logic [21:0] acc,
    output logic done
);

    logic run;
    logic [3:0] cnt;
    logic [21:0] acc_reg;
    logic done_reg;

    logic nxt_run;
    logic [3:0] nxt_cnt;
    logic [21:0] nxt_acc;
    logic nxt_done;

    // combinational sum of the four 8x8 products
    logic [17:0] sum_prods;
    logic [15:0] prod0, prod1, prod2, prod3;

    always_comb begin
        prod0 = a[0*8 +: 8] * b[0*8 +: 8];
        prod1 = a[1*8 +: 8] * b[1*8 +: 8];
        prod2 = a[2*8 +: 8] * b[2*8 +: 8];
        prod3 = a[3*8 +: 8] * b[3*8 +: 8];
        sum_prods = prod0 + prod1 + prod2 + prod3;
    end

    always_comb begin
        // hold current state by default
        nxt_run = run;
        nxt_cnt = cnt;
        nxt_acc = acc_reg;
        nxt_done = done_reg;

        if (!run && !done_reg && start) begin
            // start a new run: clear accumulator, enable running
            nxt_run = 1'b1;
            nxt_acc = 22'd0;
            nxt_cnt = 4'd0;
        end else if (run) begin
            // accumulate the sum of four products
            nxt_acc = acc_reg + sum_prods;
            if (cnt == 4'd15) begin
                // this was the 16th accumulation
                nxt_run = 1'b0;
                nxt_done = 1'b1;
                nxt_cnt = 4'd0;   // value not used while done
            end else begin
                nxt_cnt = cnt + 1'b1;
            end
        end
        // else: idle or done - hold everything
    end

    always_ff @(posedge clk) begin
        if (!rst_n) begin
            run     <= 1'b0;
            cnt     <= 4'd0;
            acc_reg <= 22'd0;
            done_reg<= 1'b0;
        end else begin
            run     <= nxt_run;
            cnt     <= nxt_cnt;
            acc_reg <= nxt_acc;
            done_reg<= nxt_done;
        end
    end

    assign acc = acc_reg;
    assign done = done_reg;

endmodule
